1	/**
2	 * Background agents — the Apparatus runs in the background, watching the
3	 * draft and surfacing sources without the writer having to ask. The model
4	 * is intentionally simple:
5	 *
6	 *   1. Watch the active folio for content changes (debounced, 45s).
7	 *   2. Derive a research query from the brief + the current draft.
8	 *   3. Skip the call if the same query was run recently (cache).
9	 *   4. Call the search provider, merge the top results into the bibliography
10	 *      with `provenance: "background"` so the panel can tell who found them.
11	 *   5. Emit `twyne:background-research` so the UI can show what is happening.
12	 *
13	 * The Convex client and a brief are required. When the client is absent
14	 * (offline) the watcher is a no-op — the writer will still see their
15	 * manually-saved sources.
16	 */
17	
18	import type { ConvexClient } from "convex/browser";
19	import { api } from "../../convex/_generated/api";
20	import type { Source } from "../../convex/research";
21	import type { ApparatusSettings, ProjectBrief } from "../types";
22	import { loadAiSettingsFromIdb, loadApparatusSettingsFromIdb } from "./idb";
23	import { runClientResearchWebSearch } from "./ai-client";
24	import {
25	  type BibEntry,
26	  loadBibliography,
27	  saveBibliography,
28	  normalizeUrl,
29	} from "./bibliography";
30	
31	const DEBOUNCE_MS = 45_000;
32	const QUERY_CACHE_TTL_MS = 5 * 60_000; // re-run same query at most every 5m
33	const MAX_BACKGROUND_PER_FOLIO = 25; // soft cap so the bib doesn't grow forever
34	const SNIPPET_MIN_CHARS = 60; // skip throwaway stubs
35	
36	interface ResearchState {
37	  lastQuery: string;
38	  lastQueryAt: number;
39	  /** Total background saves this session. */
40	  savedThisSession: number;
41	  /** Last "now researching" indicator. */
42	  lastTickAt: number;
43	  lastProvider?: string;
44	  lastStatus: "idle" | "running" | "saving" | "error";
45	  lastError?: string;
46	}
47	
48	const state: ResearchState = {
49	  lastQuery: "",
50	  lastQueryAt: 0,
51	  savedThisSession: 0,
52	  lastTickAt: 0,
53	  lastStatus: "idle",
54	};
55	
56	let debounceTimer: ReturnType<typeof setTimeout> | null = null;
57	let activeClient: ConvexClient | null = null;
58	let activeBrief: ProjectBrief | null = null;
59	let activeFolioId: string | null = null;
60	
61	function setStatus(status: ResearchState["lastStatus"], error?: string): void {
62	  state.lastStatus = status;
63	  state.lastTickAt = Date.now();
64	  if (error) state.lastError = error;
65	  notify();
66	}
67	
68	function notify(): void {
69	  if (typeof window === "undefined") return;
70	  window.dispatchEvent(
71	    new CustomEvent("twyne:background-research", { detail: snapshot() }),
72	  );
73	}
74	
75	export function snapshot() {
76	  return {
77	    lastQuery: state.lastQuery,
78	    lastQueryAt: state.lastQueryAt,
79	    savedThisSession: state.savedThisSession,
80	    lastTickAt: state.lastTickAt,
81	    status: state.lastStatus,
82	    error: state.lastError,
83	    activeFolioId,
84	    provider: state.lastProvider,
85	  };
86	}
87	
88	/** Derive a research query from the brief + current draft. */
89	export function deriveQuery(
90	  brief: ProjectBrief | null,
91	  draftText: string,
92	): string {
93	  const a = brief?.answers;
94	  const fragments: string[] = [];
95	  if (a?.workingTitle) fragments.push(a.workingTitle);
96	  if (a?.audience) fragments.push(`for ${a.audience}`);
97	  if (a?.goal) fragments.push(a.goal);
98	  if (a?.tone) fragments.push(`tone: ${a.tone}`);
99	  if (a?.format) fragments.push(`format: ${a.format}`);
100	  const trimmed = draftText.trim().slice(0, 280);
101	  if (trimmed) fragments.push(trimmed);
102	  return fragments.join(" · ").trim();
103	}
104	
105	/** Hash a query to dedupe. */
106	function hashQuery(q: string): string {
107	  // Cheap FNV-1a — we don't need crypto, just stable identity.
108	  let h = 0x811c9dc5;
109	  for (let i = 0; i < q.length; i++) {
110	    h ^= q.charCodeAt(i);
111	    h = Math.imul(h, 0x01000193);
112	  }
113	  return (h >>> 0).toString(36);
114	}
115	
116	function sameAsRecent(q: string): boolean {
117	  return (
118	    hashQuery(q) === hashQuery(state.lastQuery) &&
119	    Date.now() - state.lastQueryAt < QUERY_CACHE_TTL_MS
120	  );
121	}
122	
123	/** Stop any pending or running work. */
124	export function stopBackgroundResearch(): void {
125	  if (debounceTimer) {
126	    clearTimeout(debounceTimer);
127	    debounceTimer = null;
128	  }
129	  setStatus("idle");
130	}
131	
132	/** Configure the research watcher. Safe to call repeatedly — the latest
133	 *  args win. */
134	export function startBackgroundResearch(args: {
135	  client: ConvexClient | null;
136	  brief: ProjectBrief | null;
137	  folioId: string | null;
138	}): void {
139	  activeClient = args.client;
140	  activeBrief = args.brief;
141	  activeFolioId = args.folioId;
142	  // No client = no remote research; mark idle but still emit a tick so
143	  // the UI knows we're listening.
144	  setStatus(activeClient ? "idle" : "idle");
145	}
146	
147	/** Re-run research now (used on folio switch and on initial load). */
148	export function kickBackgroundResearch(draftText: string): void {
149	  if (!activeFolioId) return;
150	  schedule(draftText, 0);
151	}
152	
153	/** Notify the watcher that the draft has changed. Debounced. */
154	export function onDraftChanged(draftText: string): void {
155	  if (!activeFolioId) return;
156	  schedule(draftText, DEBOUNCE_MS);
157	}
158	
159	function schedule(draftText: string, delay: number): void {
160	  if (debounceTimer) clearTimeout(debounceTimer);
161	  debounceTimer = setTimeout(() => {
162	    debounceTimer = null;
163	    void runOnce(draftText);
164	  }, delay);
165	}
166	
167	async function runOnce(draftText: string): Promise<void> {
168	  if (!activeClient || !activeFolioId) return;
169	  const query = deriveQuery(activeBrief, draftText);
170	  if (!query || query.length < 20) return; // too thin to be useful
171	  if (sameAsRecent(query)) return;
172	
173	  state.lastQuery = query;
174	  state.lastQueryAt = Date.now();
175	  setStatus("running");
176	  notify();
177	
178	  try {
179	    const context = activeBrief
180	      ? `${activeBrief.answers.audience ?? ""} · ${activeBrief.answers.goal ?? ""}`.trim()
181	      : undefined;
182	    const apparatusSettings = await loadApparatusSettingsFromIdb();
183	    const configured = await searchWithConfiguredProvider(
184	      query,
185	      context,
186	      apparatusSettings,
187	    );
188	    const res =
189	      configured ??
190	      ((activeClient
191	        ? await activeClient.action(api.research.searchSources, {
192	            query,
193	            context,
194	          })
195	        : { results: [], provider: "offline" }) as {
196	        results: Source[];
197	        provider: string;
198	      });
199	    state.lastProvider = res.provider;
200	    setStatus("saving");
201	    await persist(res.results ?? [], query);
202	    setStatus("idle");
203	  } catch (err) {
204	    setStatus("error", (err as Error).message);
205	  }
206	}
