import { describe, expect, test } from "bun:test";
import {
  buildUserPrompt,
  buildSystemPrompt,
  buildSynthesisPrompt,
  buildRubricReviewPrompt,
  buildEvidenceJudgeSystemPrompt,
  buildEvidenceJudgePrompt,
  buildIntegrityJudgeSystemPrompt,
  buildIntegrityJudgePrompt,
  toAgentPersona,
} from "../../convex/agentPrompts";
import { PERSONAS } from "./personas";

describe("persona voices", () => {
  test("every default persona ships a distinct voice spec", () => {
    for (const p of PERSONAS) {
      expect(p.voice, `${p.id} should have a voice`).toBeTruthy();
      expect(
        (p.sampleLines ?? []).length,
        `${p.id} should have sample lines`,
      ).toBeGreaterThan(0);
    }
    const voices = PERSONAS.map((p) => p.voice);
    expect(new Set(voices).size).toBe(PERSONAS.length);
  });

  test("the system prompt injects the persona's voice and lore", () => {
    const devil = PERSONAS.find((p) => p.id === "devil")!;
    const reader = PERSONAS.find((p) => p.id === "reader")!;
    const devilPrompt = buildSystemPrompt(toAgentPersona(devil));
    const readerPrompt = buildSystemPrompt(toAgentPersona(reader));

    expect(devilPrompt).toContain("WHO YOU ARE");
    expect(devilPrompt).toContain(devil.voice!.slice(0, 24));
    // Two different editors must produce materially different prompts.
    expect(devilPrompt).not.toBe(readerPrompt);
  });

  test("personas with no voice fall back to the generic instruction", () => {
    const prompt = buildSystemPrompt({
      id: "x",
      name: "Plain",
      role: "tester",
      description: "d",
      focus: "f",
    });
    expect(prompt).toContain("Speak in your own voice");
  });
});

describe("synthesis + review prompts", () => {
  test("synthesis prompt lists each editor's memo", () => {
    const out = buildSynthesisPrompt(
      [
        { personaName: "A", role: "critic", text: "memo-a" },
        { personaName: "B", role: "reader", text: "memo-b" },
      ],
      null,
    );

/**
 * AI orchestrator — routes calls through the priority chain:
 *
 *   1. Client-side AI (BYOK) — if user has configured providers
 *   2. Convex server action — the existing server-side path
 *   3. Local deterministic fallback — always works, no network
 *
 * All panels import this instead of calling Convex actions directly,
 * so BYOK is transparently enabled everywhere.
 */

import type { AiSettings, AiFeature } from "../types";
import { loadAiSettingsFromIdb } from "./idb";
import {
  hasConfiguredAiProvider,
  runClientAgent,
  normalizeAiSettings,
} from "./ai-client";
import type { AgentRequest, AgentResponse } from "../../convex/agentPrompts";
import type { ConvexClient } from "convex/browser";
import { reportApplicationDiagnostic } from "./application-diagnostics";

/* ── Cached settings ────────────────────────────────────────────── */

let _cachedSettings: AiSettings | null = null;

export async function getCachedAiSettings(): Promise<AiSettings> {
  if (_cachedSettings) return _cachedSettings;
  const raw = await loadAiSettingsFromIdb();
  _cachedSettings = normalizeAiSettings(raw);
  return _cachedSettings;
}

export function invalidateAiSettingsCache(): void {
  _cachedSettings = null;
}

/* ── Convenience: run with full fallback chain ──────────────────── */

export interface OrchestratorOptions {
  feature: AiFeature;
  req: AgentRequest;
  client: ConvexClient | null;
  serverAction?: () => Promise<AgentResponse>;
  localFallback?: () => AgentResponse;
}

export async function runAiWithFallback(
  opts: OrchestratorOptions,
): Promise<AgentResponse> {
  // 1. Try client-side AI
  const settings = await getCachedAiSettings();
  if (hasConfiguredAiProvider(settings)) {
    const clientResult = await runClientAgent(opts.feature, opts.req, settings);
    if (clientResult) {
      // Tag with "client" prefix so UI can distinguish
      return {
        ...clientResult,
        provider:
          `client-${clientResult.provider}` as AgentResponse["provider"],
      };
    }
  }

  // 2. Try server action
  if (opts.serverAction) {
    try {
      return await opts.serverAction();
    } catch (err) {
      reportApplicationDiagnostic(
        `twyne:ai-orchestrator:${opts.feature}`,
        err,
        { feature: opts.feature },
      );
    }
  }

  // 3. Local fallback
  if (opts.localFallback) {
    return opts.localFallback();
  }

  // Ultimate fallback — should never reach here if localFallback is provided
  return {
    text: "The room is quiet. Try again when connected.",
    type: "perspective",
    provider: "local",
  };
}

/* ── Provider tag display helper ────────────────────────────────── */

export function formatProviderTag(
  provider: AgentResponse["provider"] | string,
): string {
  if (provider.startsWith("client-")) {
    const name = provider.slice(7);
    return `client:${name}`;
  }
  return provider;
}
