122	/** Side-margin rem values for the legacy coarse {@link DocMargin} presets. */
123	export const MARGIN_PRESET_REM: Record<DocMargin, number> = {
124	  tight: 1.5,
125	  normal: 3,
126	  roomy: 5,
127	};
128	
129	/** Allowed slider range (rem) for each adjustable page margin. */
130	export const MARGIN_RANGE = {
131	  x: { min: 0, max: 8, step: 0.25 },
132	  top: { min: 0, max: 8, step: 0.25 },
133	  bottom: { min: 0, max: 8, step: 0.25 },
134	} as const;
135	
136	/**
137	 * Resolve the effective numeric page margins (in rem) for a layout, applying
138	 * sensible fallbacks so documents saved before numeric margins existed still
139	 * render correctly.
140	 */
141	export function resolveMargins(layout: LayoutSettings): {
142	  x: number;
143	  top: number;
144	  bottom: number;
145	} {
146	  const presetX = MARGIN_PRESET_REM[layout.margin] ?? MARGIN_PRESET_REM.normal;
147	  const x = layout.marginX ?? presetX;
148	  const top = layout.marginTop ?? (layout.margin === "roomy" ? 5 : 2.5);
149	  const bottom = layout.marginBottom ?? (layout.margin === "roomy" ? 5 : 4);
150	  return { x, top, bottom };
151	}
