492	export interface JudgeResult {
493	  personaId: string;
494	  score: number;
495	  rationale: string;
496	  provider: string;
497	}
498	
499	export interface RubricCombineResult {
500	  judgeMean: number; // 0-10
501	  minJudge: number; // 0-10, the harshest judge's score
502	  staticTotal: number; // 0-10
503	  combined: number; // 0-100
504	  grade: string;
505	  summary: string;
506	}
507	
508	const JUDGE_WEIGHT = 0.45;
509	const MIN_JUDGE_WEIGHT = 0.35;
510	const STATIC_WEIGHT = 0.2;
511	
512	export function combineJudgesAndStatic(
513	  judges: JudgeResult[],
514	  staticScore: StaticScore,
515	  brief: { answers: { audience: string; goal: string } } | null,
516	): RubricCombineResult {
517	  // Mean across judges, with a hard penalty for any judge below 4.
518	  const mean =
519	    judges.length > 0
520	      ? judges.reduce((s, j) => s + j.score, 0) / judges.length
521	      : 5;
522	  const lowJudges = judges.filter((j) => j.score < 4).length;
523	  const lowPenalty = lowJudges * 0.4; // each low judge drags the mean
524	  const judgeMean = clamp(1, 10, mean - lowPenalty);
525	
526	  // The harshest single judge, weighted heavily on its own — one persona
527	  // calling the draft broken shouldn't get diluted away by an average.
528	  const minJudge =
529	    judges.length > 0 ? clamp(0, 10, Math.min(...judges.map((j) => j.score))) : 5;
530	
531	  const staticTotal = staticScore.total;
532	
533	  // Combined score on a 0-10 scale, then mapped to 0-100 with a curve
534	  // designed to be brutal. Most drafts should land in the 40-65 range;
535	  // a 90+ is reserved for genuinely excellent work.
536	  const combinedTen =
537	    judgeMean * JUDGE_WEIGHT +
538	    minJudge * MIN_JUDGE_WEIGHT +
539	    staticTotal * STATIC_WEIGHT;
540	  const combinedHundred = brutalCurve(combinedTen * 10);
541	  const grade = letterGrade(combinedHundred);
542	
543	  return {
544	    judgeMean,
545	    minJudge,
546	    staticTotal,
547	    combined: Math.round(combinedHundred),
548	    grade,
549	    summary: buildSummary(judges, staticScore, combinedHundred, brief),
550	  };
551	}
552	
553	/**
554	 * The brutal curve. We compress the 60-80 band and stretch the
555	 * 90+ band so that only really strong work gets there. This is by
556	 * design — Twyne is for writers who want editorial pressure, not for
557	 * a self-esteem mirror.
558	 */
559	function brutalCurve(rawHundred: number): number {
560	  // Anchor the curve at these points:
561	  //   50 raw  →  50 final (a C-grade draft stays a C)
562	  //   60 raw  →  58
563	  //   70 raw  →  67
564	  //   80 raw  →  76
565	  //   90 raw  →  86
566	  //   95 raw  →  93
567	  //  100 raw  → 100
568	  if (rawHundred <= 50) return Math.max(0, rawHundred);
569	  if (rawHundred >= 95) return Math.min(100, 93 + (rawHundred - 95) * 1.4);
570	  // Linear in 50-95 band
571	  return 50 + (rawHundred - 50) * (43 / 45);
572	}
