        await flushArize();
        return { ...parsed, provider: provider.label };
      }
    } catch (err) {
      console.error("[twyne:agents] target-fit judge call failed:", err);
    }
    await flushArize();
    return localTargetFit(brief, args.draftText);
  },
});

