import {
  IDLE_MS,
  MAX_PASSES_PER_SESSION,
  MIN_INTERVAL_MS,
  WORD_DELTA_THRESHOLD,
  __resetForTests,
  onDraftChanged,
  snapshot,
  startBackgroundRoom,
  stopBackgroundRoom,
  whyNotReady,
} from "./background-room";
